[Fact]
public async Task CompleteLesson_creates_review_states()
{
    await using var app = new SkillforgeWebApplicationFactory();
    var client = app.CreateAuthenticatedClient("user-1");

    var response = await client.PostAsync("/lessons/lesson-1/complete", null);

    response.EnsureSuccessStatusCode();
    await app.AssertReviewStatesCreatedAsync("user-1", "lesson-1");
