public sealed class StreakService(TimeProvider time)
{
    public bool IsBroken(DateOnly lastActive) =>
        DateOnly.FromDateTime(time.GetUtcNow().UtcDateTime) > lastActive.AddDays(1);
}

[Fact]
public void Streak_breaks_after_a_missed_day()
{
    var time = new FakeTimeProvider(new DateTimeOffset(2026, 6, 16, 9, 0, 0, TimeSpan.Zero));
    var service = new StreakService(time);

    Assert.True(service.IsBroken(new DateOnly(2026, 6, 14)));
}
